package io.github.ningpp.compat;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;

/**
 * Replacement for System.Runtime.CompilerServices.RuntimeHelpers (generated by
 * CSharpToJava converter).
 */
public final class RuntimeHelpers {

    private RuntimeHelpers() {
    }

    /**
     * C# RuntimeHelpers.IsReferenceOrContainsReferences&lt;T&gt;() — reports whether
     * T is a reference type or a value type that contains references. Java erases the
     * type argument, so the only answer that is safe for every T is true: the callers
     * use this to decide whether an array must be cleared, and clearing a primitive
     * array is harmless.
     *
     * @return Always true.
     */
    public static boolean isReferenceOrContainsReferences() {
        return true;
    }

    /**
     * C# RuntimeHelpers.GetHashCode(object) — the identity based hash code, which
     * ignores any Object.hashCode() override (used by the default object comparer and
     * by reference equality comparers). Returns 0 for null, as C# does.
     *
     * @param obj The object for which the identity hash code is requested.
     * @return The identity hash code of the object, or 0 when it is null.
     */
    public static int getHashCode(Object obj) {
        return System.identityHashCode(obj);
    }

    /**
     * C# RuntimeHelpers.GetUninitializedObject(Type) — allocates an instance without
     * running any constructor. Arrays, interfaces, primitives and abstract types have
     * no uninitialized instance and are rejected, as in C#.
     *
     * @param type The type to allocate.
     * @return An instance of the type whose fields all hold their default values.
     */
    public static Object getUninitializedObject(Class<?> type) {
        if (type == null) {
            throw new ArgumentNullException("type");
        }
        if (type.isArray() || type.isInterface() || type.isPrimitive() || Modifier.isAbstract(type.getModifiers())) {
            throw new ArgumentException("Cannot create an uninitialized instance of " + type.getName() + ".");
        }
        Object instance = allocateWithUnsafe(type);
        if (instance != null) {
            return instance;
        }
        // No unsafe allocation available on this JVM: fall back to the parameterless
        // constructor, which is the closest representable approximation (it does run
        // field initializers, unlike GetUninitializedObject).
        try {
            Constructor<?> constructor = type.getDeclaredConstructor();
            constructor.setAccessible(true);
            return constructor.newInstance();
        } catch (ReflectiveOperationException | RuntimeException e) {
            throw new PlatformNotSupportedException("Cannot create an uninitialized instance of " + type.getName() + " on this JVM.");
        }
    }

    /**
     * Allocates an instance through sun.misc.Unsafe.allocateInstance, which is how the
     * JVM itself allocates an object without running a constructor.
     *
     * @param type The type to allocate.
     * @return The uninitialized instance, or null when unsafe allocation is unavailable.
     */
    private static Object allocateWithUnsafe(Class<?> type) {
        try {
            Class<?> unsafeType = Class.forName("sun.misc.Unsafe");
            Field instanceField = unsafeType.getDeclaredField("theUnsafe");
            instanceField.setAccessible(true);
            Object unsafe = instanceField.get(null);
            Method allocateInstance = unsafeType.getMethod("allocateInstance", Class.class);
            return allocateInstance.invoke(unsafe, type);
        } catch (ReflectiveOperationException | RuntimeException | LinkageError e) {
            return null;
        }
    }
}
